    "content": "湖风徐来，碧波如练。岭南园的亭台楼榭间，几对新人正预约拍摄、等待领证，琉璃瓦顶映着新人笑靥；雕塑园旁，“花语书房”自助图书馆内，市民游客临窗而坐、静心翻阅。一湖碧水之畔，婚俗新风与书香文脉交织，一派其乐融融的城市生活景象。"
