    "content": "新华社西宁11月11日电 记者手记：关于柏大卫故事的十个细节 新华社记者白玛央措、李欢 95岁的美国老人柏大卫，在青海湟源度过了童年和少年时光。18岁离开，阔别38年后重返湟源，此后又一次次跨越重洋，为当地筹赠医疗设备、支持教育。他始终认定：“一个人一生只能有一个故乡，我的故乡就是湟源。” 记者通过越洋连线与老人隔屏相见，也走进他生活、长大的湟源县城，寻找往事留下的痕迹。在这里，有他惦念多年的人，也有至今牵挂着他的乡亲。沿着这些交往，记者记录下十个细节，进一步了解这位美国老人和他的中国故乡。 “黑饭” 11月2日，…"
