    "content": "金渐层、缅因猫、布偶猫……这些市场上卖大几百甚至上千元的品种猫竟可以“免费领养”？近日，人民日报曝光部分宠物店打着“免费领养”旗号诱导消费者分期付款、捆绑销售宠物用品的“猫贷”套路，引发广泛关注。 在“猫贷”套路中，所谓的“免费领养”其实早在暗中标好了价格：指定的宠物用品和宠物服务看似为“回本”，其实价格高于市场同类产品；每月扣款金额好像不多，两年合计下来的总价远超宠物市场价。更有甚者，有些小猫本就是病猫，领养人不仅要自费医治，不治死亡后竟还要接着还款，否则便会遭到店家的征信威胁。 更值得警惕的是，“猫贷”套路正精…"
