    "description": "时序深秋，皖南古村秋色正浓。在安徽省黄山市黟县宏村镇，卢村、塔川村等古村落在晨雾中若隐若现，粉墙黛瓦与斑斓秋叶相映成趣；奇墅湖面霞光洒落，水雾氤氲；山野间乌桕渐红，层林尽染，游客们漫步其间，宛如走进一幅色彩斑斓的诗意画卷。 记者：黄博涵 摄制：施亚磊、李飞",
