    "content": "编者按： 2026年是伟大的民族英雄、伟大的爱国主义者、中国民主革命的伟大先驱孙中山先生诞辰160周年。港澳地区是孙中山先生早年求学、行医的地方，也是他革命思想的重要策源地、革命事业的重要承载地。值此具有特殊历史意义的时刻，中国新闻社推出系列专题片《潮起南天——孙中山的港澳求索》，回顾孙中山先生在港澳探寻救国道路的思想历程和革命实践，重温他在港澳领导民主革命的峥嵘岁月。 1892年，年仅26岁的孙中山先生应澳门镜湖医院会董的邀请，担任义务西医，成为镜湖医院历史上第一位华人西医，开启了他在澳门悬壶济世、结交仁人的生涯…"
