    "link": "https://36kr.com/newsflashes/4064657481077635?f=rss",
    "pub_date": "2026-11-11 09:03:24",
    "author": "",
    "description": "36氪获悉，华泰证券研报称，截至11月9日，涌益全国生猪均价8.6元/公斤，跌破本轮周期前次低点。华泰证券认为，近期猪价二次探底超出市场与产业预期，主要系行业供给与库存压力仍较大而消费需求承接较弱，第四季度生猪养殖行业旺季不旺基本确立。展望后市，随着猪价与仔猪价格再度刷新前低，行业现金流亏损加剧，或带动能繁母猪产能去化超预期演绎，为远期的猪价弹性及持续性打开空间，而板块持仓仍处相对底部，华泰证券重申生猪板块的布局机会。",
