    "description": "中新网巴黎11月11日电 (记者 李洋)当地时间11月10日，第八届中法文化论坛·温州菜品鉴活动在位于法国巴黎的联合国教科文组织总部举行。活动由浙江省温州市文化广电旅游局承办，在法温籍侨胞协助下，以温州菜为媒介，搭建起美食文化的桥梁，为这场文化对话注入了“温州味道”。",
    "content": "中新网巴黎11月11日电 (记者 李洋)当地时间11月10日，第八届中法文化论坛·温州菜品鉴活动在位于法国巴黎的联合国教科文组织总部举行。活动由浙江省温州市文化广电旅游局承办，在法温籍侨胞协助下，以温州菜为媒介，搭建起美食文化的桥梁，为这场文化对话注入了“温州味道”。"
