    "description": "新华社首尔11月11日电（记者张粲 孙一然）据韩国纽西斯通讯社报道，京畿道城南市盆唐区野塔洞一处公交车站附近11日上午发生交通事故，一辆公交车连续撞击多辆轿车，已造成34人受伤。 据报道，事故发生在当地时间11日7时34分许。当时，一辆公交车在连续撞击约10辆正等待交通信号灯的轿车后，撞上道路中央隔离带。接到目击者报警后，京畿道消防部门派员赶赴现场开展救援。警方等部门正在调查事故原因。",
