    "content": "荷兰晶片制造商安世半导体（Nexperia）临时首席执行官蒂尔格星期二（11月10日）向路透社称，尽管公司一年多前因地缘政治紧张局势与中国业务分离，双方如今已各自独立运营，但未来仍有重新整合的可能。 蒂尔格在德国慕尼黑举行的2026年国际电子元器件博览会期间接受采访时说，如果双方最终永久分离，安世半导体的中国母公司闻泰科技就应获得补偿。 蒂尔格说：“他们是公司股份的实际权益持有人，目前却无法行使控制权。但如果未来启动出售程序，他们理应获得公平补偿。” 蒂尔格也表示，他相信，只要不会对欧洲经济和产业构成风险，荷兰及欧…"
