    "description": "2026年11月11日 新华社北京11月10日电 中共中央党史和文献研究院编辑的习近平同志《论减贫脱贫》，近日由中央文献出版社出版，在全国发行。 这部专题文集，收入习近平同志关于减贫脱贫的重要文稿55篇，其中部分文稿是首次公开发表。 消除贫困，是人类共同理想。消除贫困、改善民生、实现共同富裕，是中国特色社会主义的本质要求，是中国共产党的重要使命。党的十八大以来，以习近平同志为核心的党中央把脱贫攻坚摆在治国理政的突出位置，作为全面建成小康…",
    "content": "2026年11月11日 新华社北京11月10日电&nbsp;&nbsp;中共中央党史和文献研究院编辑的习近平同志《论减贫脱贫》，近日由中央文献出版社出版，在全国发行。 这部专题文集，收入习近平同志关于减贫脱贫的重要文稿55篇，其中部分文稿是首次公开发表。 消除贫困，是人类共同理想。消除贫困、改善民生、实现共同富裕，是中国特色社会主义的本质要求，是中国共产党的重要使命。党的十八大以来，以习近平同志为核心的党中央把脱贫攻坚摆在治国理政的突出位置，作为全面建成小康社会的底线任务，组织开展声势浩大的脱贫攻坚战并取得全面胜利…"
