    "description": "2026年11月11日 我出使澳大利亚是从北京一路向南飞到悉尼，航程跨越亚洲和太平洋广袤的土地与海域。10个小时后，望见舷窗外悉尼歌剧院的轮廓，我不由深思：以澳大利亚人的视角，亚洲是近是远？是否自认是亚太大家庭的一员？澳大利亚的未来在哪里？ 带着这些问题，我抵达首都堪培拉后交流的首个澳大利亚学者，就是被誉为“亚太经合组织（APEC）学术之父”的德赖斯代尔教授。88岁的老先生向我娓娓道来协助时任澳大利亚总理霍克于1989年倡导并推动成立A…",
    "content": "2026年11月11日 我出使澳大利亚是从北京一路向南飞到悉尼，航程跨越亚洲和太平洋广袤的土地与海域。10个小时后，望见舷窗外悉尼歌剧院的轮廓，我不由深思：以澳大利亚人的视角，亚洲是近是远？是否自认是亚太大家庭的一员？澳大利亚的未来在哪里？ 带着这些问题，我抵达首都堪培拉后交流的首个澳大利亚学者，就是被誉为“亚太经合组织（APEC）学术之父”的德赖斯代尔教授。88岁的老先生向我娓娓道来协助时任澳大利亚总理霍克于1989年倡导并推动成立APEC的历史，讲述澳大利亚如何高举开放的区域主义和自由贸易旗帜、打破孤悬大洋的地…"
